var i=`retry-timeout-and-backoff-patterns`;var o=50;var r={en:[{id:`T050-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Retry, Timeout & Backoff Patterns`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Consensus allows distributed participants to agree on a sequence of decisions despite certain failures.`},{id:`B`,text:`CAP states that, when a network partition occurs, a distributed data system cannot guarantee both linearizable consistency and availability for every request.`},{id:`C`,text:`PACELC extends CAP: if partitioned, choose between availability and consistency; else, even in normal operation, choose between latency and consistency.`},{id:`D`,text:`Timeouts bound waiting, retries recover transient failures, and backoff spaces repeated attempts to avoid overload.`}]},{id:`T050-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Retry, Timeout & Backoff Patterns`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`A strongly consistent cross-region read may require waiting for remote coordination, while a local replica responds faster with possible staleness.`},{id:`B`,text:`Under partition, a consistency-oriented system may reject or delay operations to avoid contradictory answers; an availability-oriented system may accept operations that reconcile later.`},{id:`C`,text:`Use request-scoped idempotency keys, deduplication stores and atomic association of a result with its key.`},{id:`D`,text:`Use finite deadlines, exponential backoff with jitter, retryable-error classification and limits on attempt count.`}]},{id:`T050-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`Retry, Timeout & Backoff Patterns`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`A client retries a card payment after timeout. Reusing its idempotency key must return the original outcome, not issue a second charge, even if the first response was lost.`},{id:`B`,text:`After a user changes their profile avatar, one region may briefly show the old image. A versioned asset URL can ensure the user's subsequent reads display the newly uploaded version.`},{id:`C`,text:`A webhook delivery retries 503 responses with jitter for a bounded period, but a malformed 400 request goes to a dead-letter workflow instead of looping indefinitely.`},{id:`D`,text:`An order transaction creates a payment record and deducts store credit in one commit. If the write fails, neither partial operation should become visible as successful.`}]},{id:`T050-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Retry, Timeout & Backoff Patterns`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`ACID does not guarantee that your business logic is correct or that external email/card APIs participate atomically.`},{id:`B`,text:`'Last write wins' can silently discard legitimate updates.`},{id:`C`,text:`Do not classify every database permanently as CA, CP or AP; behavior is operation-specific and depends on fault assumptions.`},{id:`D`,text:`Blindly retrying card charges can double-bill; long timeouts can exhaust connection pools.`}]},{id:`T050-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`They should be designed together with idempotency and end-to-end latency budgets.`}]}]},{id:`T050-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Retrying every failed request immediately is always the safest policy.`}]}]},{id:`T050-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Define failure visibility and dead-letter or reconciliation paths for exhausted retries.`}]}]},{id:`T050-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Retry, Timeout & Backoff Patterns`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Leader election prevents split-brain without quorum or fencing safeguards.`},{id:`B`,text:`Retrying a non-idempotent payment cannot cause duplicate charges.`},{id:`C`,text:`Timeouts bound waiting, retries recover transient failures, and backoff spaces repeated attempts to avoid overload.`},{id:`D`,text:`Use finite deadlines, exponential backoff with jitter, retryable-error classification and limits on attempt count.`}]},{id:`T050-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Retry, Timeout & Backoff Patterns`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Retrying every failed request immediately is always the safest policy.`},{id:`B`,text:`When no partition exists, PACELC makes no consistency-latency trade-off.`},{id:`C`,text:`Define failure visibility and dead-letter or reconciliation paths for exhausted retries.`},{id:`D`,text:`A webhook delivery retries 503 responses with jitter for a bounded period, but a malformed 400 request goes to a dead-letter workflow instead of looping indefinitely.`}]},{id:`T050-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A webhook delivery retries 503 responses with jitter for a bounded period, but a malformed 400 request goes to a dead-letter workflow instead of looping indefinitely.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Have an agent implement a webhook client with deadlines, capped exponential backoff and jitter. Verify attempt limits, classification of permanent errors and idempotent delivery.`},{id:`B`,text:`Have an agent simulate delayed replica propagation for profile edits. Define conflict resolution, read-after-write expectations and tests ensuring convergence after messages arrive.`},{id:`C`,text:`Have an agent implement an order-credit transaction with invariant tests, forced rollback, and concurrent withdrawals. Document the actual configured isolation level.`},{id:`D`,text:`Ask an agent to design reservation confirmation under a simulated partition, specifying exact success, timeout and retry semantics rather than a generic CP/AP label.`}]},{id:`T050-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`How can retries at three nested layers amplify traffic during an outage?`}]}]},{id:`T050-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A webhook delivery retries 503 responses with jitter for a bounded period, but a malformed 400 request goes to a dead-letter workflow instead of looping indefinitely.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Retry, Timeout & Backoff Patterns`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T050-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A webhook delivery retries 503 responses with jitter for a bounded period, but a malformed 400 request goes to a dead-letter workflow instead of looping indefinitely.`,b:!0},{t:` — propose three checks for `},{t:`Retry, Timeout & Backoff Patterns`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T050-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A webhook delivery retries 503 responses with jitter for a bounded period, but a malformed 400 request goes to a dead-letter workflow instead of looping indefinitely.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T050-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Retry, Timeout & Backoff Patterns`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A webhook delivery retries 503 responses with jitter for a bounded period, but a malformed 400 request goes to a dead-letter workflow instead of looping indefinitely.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T050-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Повтори, тайм-аути та backoff`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Консенсус дозволяє розподіленим учасникам узгодити послідовність рішень попри певні відмови.`},{id:`B`,text:`CAP стверджує, що за мережевого розділення розподілене сховище не може одночасно гарантувати лінеаризовану узгодженість та доступність кожного запиту.`},{id:`C`,text:`PACELC розширює CAP: за partition постає вибір між доступністю й узгодженістю; в нормальному режимі — між затримкою й узгодженістю.`},{id:`D`,text:`Timeout обмежує очікування, retry долає тимчасові збої, backoff розносить спроби в часі, щоб не перевантажувати систему.`}]},{id:`T050-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Повтори, тайм-аути та backoff`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Сильно узгоджене читання між регіонами може чекати віддаленої координації, тоді як локальна репліка відповідає швидше, але іноді застаріло.`},{id:`B`,text:`Під час partition система, орієнтована на узгодженість, відхиляє або затримує операції; орієнтована на доступність може приймати зміни з подальшим узгодженням.`},{id:`C`,text:`Застосовуйте ключі ідемпотентності, сховище дедуплікації та атомарне зв’язування ключа з результатом.`},{id:`D`,text:`Використовуйте кінцевий deadline, експоненційний backoff з jitter, класифікацію помилок і ліміти спроб.`}]},{id:`T050-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Повтори, тайм-аути та backoff`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Клієнт повторює картковий платіж після timeout. Повтор ключа має повертати початковий результат, а не виконувати друге списання, навіть якщо перша відповідь загубилась.`},{id:`B`,text:`Після зміни аватара один регіон може деякий час показувати старий. URL із версією допомагає забезпечити відображення нового зображення під час наступних читань користувача.`},{id:`C`,text:`Доставка webhook повторює 503 з jitter протягом обмеженого часу, але некоректний 400 переходить у dead-letter процес замість нескінченного циклу.`},{id:`D`,text:`Транзакція замовлення створює запис платежу та списує кредит магазину одним commit. Якщо запис не вдався, жоден частковий результат не має вважатися успіхом.`}]},{id:`T050-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Повтори, тайм-аути та backoff`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`ACID не гарантує коректність ваших бізнес-правил чи атомарність зовнішнього email/платіжного API.`},{id:`B`,text:`«Останній запис перемагає» може непомітно втратити коректне оновлення.`},{id:`C`,text:`Не навішуйте назавжди ярлик CA, CP чи AP на будь-яку БД: поведінка залежить від операцій і моделі відмов.`},{id:`D`,text:`Сліпі повтори платіжного списання можуть подвоїти оплату; довгі timeout виснажують пул з’єднань.`}]},{id:`T050-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Їх слід проєктувати разом з ідемпотентністю й бюджетом затримки.`}]}]},{id:`T050-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Негайно повторювати кожен невдалий запит — завжди найбезпечніша політика.`}]}]},{id:`T050-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Потрібні видимі помилки, dead-letter або звірка після вичерпання спроб.`}]}]},{id:`T050-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Повтори, тайм-аути та backoff`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Вибір лідера запобігає split-brain без кворуму чи fencing-механізмів.`},{id:`B`,text:`Повтор неідемпотентного платежу не може спричинити подвійне списання.`},{id:`C`,text:`Timeout обмежує очікування, retry долає тимчасові збої, backoff розносить спроби в часі, щоб не перевантажувати систему.`},{id:`D`,text:`Використовуйте кінцевий deadline, експоненційний backoff з jitter, класифікацію помилок і ліміти спроб.`}]},{id:`T050-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Повтори, тайм-аути та backoff`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Негайно повторювати кожен невдалий запит — завжди найбезпечніша політика.`},{id:`B`,text:`Коли розділення немає, PACELC не описує компроміс узгодженості й затримки.`},{id:`C`,text:`Потрібні видимі помилки, dead-letter або звірка після вичерпання спроб.`},{id:`D`,text:`Доставка webhook повторює 503 з jitter протягом обмеженого часу, але некоректний 400 переходить у dead-letter процес замість нескінченного циклу.`}]},{id:`T050-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Доставка webhook повторює 503 з jitter протягом обмеженого часу, але некоректний 400 переходить у dead-letter процес замість нескінченного циклу.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента реалізувати webhook-клієнт із deadline, обмеженим експоненційним backoff та jitter. Перевірте ліміт спроб, постійні помилки й ідемпотентність.`},{id:`B`,text:`Попросіть агента змоделювати затриману реплікацію змін профілю. Визначте правила конфліктів, очікування після власного запису та тести зближення після доставки подій.`},{id:`C`,text:`Попросіть агента реалізувати транзакцію замовлення й кредиту з тестами інваріантів, примусовим rollback та конкурентними списаннями. Задокументуйте рівень ізоляції.`},{id:`D`,text:`Попросіть агента спроєктувати підтвердження бронювання під час мережевого розділення, явно визначити успіх, timeout і повтори замість загальної позначки CP/AP.`}]},{id:`T050-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Як повтори в трьох вкладених шарах підсилюють трафік під час збою?`}]}]},{id:`T050-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Доставка webhook повторює 503 з jitter протягом обмеженого часу, але некоректний 400 переходить у dead-letter процес замість нескінченного циклу.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Повтори, тайм-аути та backoff`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T050-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Доставка webhook повторює 503 з jitter протягом обмеженого часу, але некоректний 400 переходить у dead-letter процес замість нескінченного циклу.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Повтори, тайм-аути та backoff`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T050-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Доставка webhook повторює 503 з jitter протягом обмеженого часу, але некоректний 400 переходить у dead-letter процес замість нескінченного циклу.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T050-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Повтори, тайм-аути та backoff`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Доставка webhook повторює 503 з jitter протягом обмеженого часу, але некоректний 400 переходить у dead-letter процес замість нескінченного циклу.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var a={slug:i,topicId:50,questions:r};export{a as default,r as questions,i as slug,o as topicId};